#include <deque>
#include <vector>

int main() {
    std::deque<int> d = {10, 20};
    int& d_ref = d[0]; // Reference to 10
    auto d_it = d.begin(); // Iterator to 10

    d.push_back(30); // O(1)

    // d_it is INVALIDATED. Accessing it is UB.
    // d_ref is VALID, still refers to 10.
    // std::cout << d_ref; // Safe

    std::vector<int> v = {10, 20};
    int& v_ref = v[0]; // Reference to 10

    // Assuming current capacity is 2, push_back forces reallocation
    v.push_back(30); 

    // v_ref is INVALIDATED. Accessing it is UB if reallocation occurred.
}
